here's an example class for a physical object:

```
class object {
   private:
      float mass;
      float x, y, z;
      float vx, vy, vz;
   public:
      object(float m, float x, float y, float z, float vx, float vy, float vz) {
         this->mass = m;
         this->x = x;
         this->y = y;
         this->z = z;
         this->vx = vx;
         this->vy = vy;
         this->vz = vz;
      }
      void setposition(float x, float y, float z) {
         this->x = x;
         this->y = y;
         this->z = z;
      }
      void setvelocity(float vx, float vy, float vz) {
         this->vx = vx;
         this->vy = vy;
         this->vz = vz;
      }
      float getmass() { return mass; }
      float getx() { return x; }
      float gety() { return y; }
      float getz() { return z; }
      float getvx() { return vx; }
      float getvy() { return vy; }
      float getvz() { return vz; }
};
```

this class contains properties for mass, position (x, y, z), and velocity (vx, vy, vz). It also includes getters and setters for these properties. You can create similar classes for different physical systems.

