```html
<!DOCTYPE html>
<html>
<head>
    <title>Random Color Generator</title>
</head>
<body>
    <h1>Random Color Generator</h1>
    <p>Click the button below to generate a new random color:</p>
    <button onclick="generateColor()">Generate Color</button>
    <div id="colorDisplay" style="margin-top: 20px; width: 100px; height: 100px; border: 2px solid black;"></div>
    <div id="colorCode" style="margin-top: 10px;"></div>
    <button onclick="copyColorCode()">Copy Color Code</button>
    <button onclick="saveColorCode()">Save Color Code</button>
    <ul id="colorList"></ul>

    <script>
        var colors = [];

        function generateColor() {
            // Generate a random color in hexadecimal format
            var color = Math.floor(Math.random()*16777215).toString(16);

            // Set the background color of the colorDisplay div to the generated color
            document.getElementById("colorDisplay").style.backgroundColor = "#" + color;

            // Show the generated color code on the page
            document.getElementById("colorCode").innerHTML = "#" + color.toUpperCase();
        }

        function copyColorCode() {
            // Get the color code element
            var colorCode = document.getElementById("colorCode");

            // Create a temporary input element to copy the color code to
            var tempInput = document.createElement("input");
            tempInput.value = colorCode.innerHTML;

            // Add the input element to the document
            document.body.appendChild(tempInput);

            // Select the input element and copy its contents to the clipboard
            tempInput.select();
            document.execCommand("copy");

            // Remove the input element from the document
            document.body.removeChild(tempInput);
        }

        function saveColorCode() {
            // Get the current color code
            var colorCode = document.getElementById("colorCode").innerHTML;

            // Add the color code to the list of saved colors
            colors.push(colorCode);

            // Clear the color code display
            document.getElementById("colorCode").innerHTML = "";

            // Clear the color display
            document.getElementById("colorDisplay").style.backgroundColor = "";

            // Clear the color list
            document.getElementById("colorList").innerHTML = "";

            // Display the list of saved colors
            for (var i=0; i<colors.length; i++) {
                var li = document.createElement("li");
                li.innerHTML = colors[i];
                document.getElementById("colorList").appendChild(li);
            }
        }
    </script>
</body>
</html>
```

The "Save Color Code" button triggers a new `saveColorCode()` function which adds the current color code to an array of saved colors, clears the color code and display, clears the list of saved colors, and displays the updated list of saved colors. The list of saved colors is displayed in a new `ul` element with the id "colorList".

